import path from "node:path";

import ts from "typescript";
import { describe, expect, it } from "vite-plus/test";

import { compilerOptions } from "./type-check.ts";

// The `#grasp` module the host generates for an App, type-checked as the
// App compiler checks App code (TypeScript 6, its options): a screen
// importing it, and a seal, type-check it with the App's own files. The
// SDK's Notes fixture is generated byte for byte as the host makes it
// (packages/sdk/test/references.test.ts), and it binds workflows with
// events, decisions and queries, so every part of a reference is in it.

const references = path.resolve(
  import.meta.dirname,
  "../../sdk/test/notes/.grasp/references.ts"
);

/** The errors TypeScript reports in `file`, as `TS<code>: <message>`. */
const errorsIn = (file: string): string[] => {
  const program = ts.createProgram([file], {
    ...compilerOptions,
    // Its declarations aren't App code: only the module's own errors count.
    skipLibCheck: true,
    paths: {},
  });
  return ts
    .getPreEmitDiagnostics(program)
    .filter((diagnostic) => diagnostic.file?.fileName === file)
    .map(
      (diagnostic) =>
        `TS${diagnostic.code}: ${ts.flattenDiagnosticMessageText(diagnostic.messageText, " ")}`
    );
};

// A whole program type-checked from cold: past the default 5 s on a
// busy runner, so the time other type-check tests have
// (apps/core/test/workflow-type-check.test.ts).
describe("the generated references", { timeout: 120_000 }, () => {
  it("type-check as the App compiler checks them, workflows and all", () => {
    expect(errorsIn(references)).toStrictEqual([]);
  });
});
